#!/usr/bin/env python3
"""insert-773-java.py の手直し（shift でずれた箇所の修正＋771対応の追加）。

gen-773-java.py を再実行したらこのスクリプトも再実行すること。
各置換は出現回数がちょうど1件（rep_all は指定件数）のときだけ適用し、
違えば失敗を報告する。

作り方：fix-772-java.py の各 rep の new 側（＝insert-772-java.py に
残った修正済みの文）を gen-773-java.py の shift() で 773 用にずらした
ものが、insert-773-java.py の旧文になる。new 側は 773 用に手で直して
ある（直す必要の無いものは旧文と同じ＝変化なしの表明）。
773 で新たに要る修正（ブロックエンティティの棚の挿入・MAX の実数値など）
は末尾の追加分にある。

注意：合成のブロックエンティティ法の rep（「合成のブロックエンティティ
（763）」〜「（769）」と「770 のブロックを追加」）はコメントの書き換え
だけが適用され、最終 return の連鎖化は行われていない。生成器の
fix_be_method の正規表現が out.append 行の末尾を `");` と期待している
が、実際の行は `")` で終わるため return が一致しない。773 の BE 合成は
棚の挿入で直接計算が壊れる（40 以降の +1 が無い）ため、RegistryRemapper.java
の 763〜771 の BE 合成 18 件は直接連鎖（772 経由）に直してある。
再生成するときはこの点を直してから使うこと。
"""
import sys
from pathlib import Path

P = Path(__file__).resolve().parent / "insert-773-java.py"
s = P.read_text(encoding="utf-8")
failed = []


def rep(old, new, label):
    global s
    n = s.count(old)
    if n != 1:
        failed.append(f"{label}: 一致 {n} 件 (期待 1 件)")
        return
    s = s.replace(old, new)


def rep_all(old, new, label, expected):
    global s
    n = s.count(old)
    if n != expected:
        failed.append(f"{label}: 一致 {n} 件 (期待 {expected} 件)")
        return
    s = s.replace(old, new)


